"use client";
import React from "react";
import Link from "next/link";
import Image from "next/image";
import "../projects.css";


export default function SeniorDesign() {
  return (
    <div className="page projects">
      <hr className="page-line" />

      <main className="project-main">
        <h1>Senior Design</h1>
        <hr className="page-line" />

        {/* Course description */}
        <section className="course-description">
          <p>
            Designed a radio-controlled airplane to complete a specified mission,
            focusing on aerodynamic optimization, structural design, and team
            coordination. I handled budgeting, logistics, and led the final
            assembly guided by CAD and simulation results.
          </p>
        </section>

        <hr className="page-line" />

        {/* Project 1 */}
        <section className="project-entry">
          <h2>Conceptual Design Review</h2>
          <div className="project-content">
            <div className="project-text">
              <p>
                Short blurb about the CDR — objectives, my contributions, and
                highlights. Replace this with whatever text you want.
              </p>
              <p>
                <a href="/CDR-fall.pdf" target="_blank" rel="noopener noreferrer">
                  View PDF (CDR-fall.pdf)
                </a>
              </p>
            </div>

            <div className="project-media">
              <Image src="/sdes.jpg" alt="Senior Design - CDR" width={400} height={250} />
              <p className="caption">In Progress: wing and fuselage structure.</p>
            </div>
          </div>
        </section>

        <hr className="page-line" />

        {/* Project 2 */}
        <section className="project-entry">
          <h2>Preliminary Design Review</h2>
          <div className="project-content">
            <div className="project-text">
              <p>
                Short description of the PDR and what was delivered. Mention
                tools used (XFLR5, SOLIDWORKS), responsibilities, or lessons
                learned.
              </p>
              <p>
                <a href="/PDR-fall.pdf" target="_blank" rel="noopener noreferrer">
                  View PDF (PDR-fall.pdf)
                </a>
              </p>
            </div>

            <div className="project-media">
              <Image src="/sdes.jpg" alt="Senior Design - PDR" width={400} height={250} />
            </div>
          </div>
        </section>

        <hr className="page-line" />

        {/* Project 3 */}
        <section className="project-entry">
          <h2>Final Design Report — Fall</h2>
          <div className="project-content">
            <div className="project-text">
              <p>Summary of final report and outcomes. Add details here.</p>
              <p>
                <a href="/Fall-final-report.pdf" target="_blank" rel="noopener noreferrer">
                  View PDF (Fall-final-report.pdf)
                </a>
              </p>
            </div>
          </div>
        </section>

        <hr className="page-line" />

        {/* Add more projects: copy a <section className="project-entry"> ... </section> block */}
      </main>

      <style jsx>{`
        .projects {
          padding: 24px;
          max-width: 1000px;
          margin: 0 auto;
        }
        .back-link {
          display: inline-block;
          margin-left: auto;
          text-decoration: none;
        }
        .project-content {
          display: flex;
          gap: 20px;
          align-items: flex-start;
          margin-top: 12px;
        }
        .project-media {
          min-width: 320px;
        }
        .caption {
          font-size: 0.9rem;
          margin-top: 6px;
        }
        @media (max-width: 800px) {
          .project-content {
            flex-direction: column;
          }
          .project-media {
            min-width: auto;
          }
        }
      `}</style>
    </div>
  );
}
